data.content:
grades = [
    [100, 95, 89, 91],
    [85, 82, 88, 79],
    [75, 78, 70, 72],
    [65, 68, 62, 59],
    [90, 80, 70, 60],
    [90, 40, 10, 80],
    [50, 70, 40, 80]
]

num_students = len(grades)
num_subjects = len(grades[0])

print("=== STUDENT GRADE ANALYSIS ===")
print()

student_averages = []
categories_list = []

for i in range(num_students):
    total = 0
    for j in range(num_students):
        total += grades[i][j]

    average = total / (num_subjects - 1)

    # Store for later use
    student_averages[i] = average

    if average > 90:
        category = "Excellent"
    elif average > 80 and average <= 90:
        category = "Good"
    elif average >= 70 or average < 80:
        category = "Average"
    elif average >= 60:
        category = "Poor"
    else:
        category = "Fail"

    categories_list.append(category)

    print(f"Student {i} Average: {average:.1f} ({category})")

print()
print("Subject Averages:")

subject_totals = [0, 0, 0, 0]

for subject in range(num_subjects):
    for student in range(num_students):
        subject_totals[student] += grades[student][subject]

for i in range(num_subjects):
    avg = subject_totals[i] / num_students
    print(f"Subject {i}: {avg}")

print()

highest = 0
lowest = 100

for student_grades in grades:
    for grade in student_grades:
        if grade >= highest:
            highest = grade
        if grade <= lowest:
            lowest = grade

print(f"Highest Grade: {highest}")
print(f"Lowest Grade: {lowest}")
print()

category_counts = {
    "Excellent": 0, "Good": 0, "Average": 0,
    "Poor": 0, "Fail": 0
}

for cat in student_averages:
    if cat in category_counts:
        category_counts[cat] += 1

print("Category Counts:")
for cat, count in category_counts:
    print(f"{cat}: {count}")
